mapper.select:
select id, name, group_manager, identify_type, user_ids, descripe,black_user_ids,create_by,create_time,update_by,update_time,remark,allow_role_name
from sys_user_group
where id = #{id}

select id, user_group_id, code, name, sort,del_flag
from sys_user_group_competition_relation
where del_flag = '0' and user_group_id = #{userGroupId}

select id, user_group_id, code, name, sort,del_flag
from sys_user_group_competition_relation
where del_flag = '0' and user_group_id = #{userGroupId}
and code = #{competitionSeriesId}

mapper.update:
update sys_user_group
name = #{name}, group_manager = #{groupManager}, identify_type = #{identifyType}, user_ids = #{userIds}, black_user_ids = #{blackUserIds}, descripe = #{descripe}, update_by = #{updateBy}, update_time = sysdate(), allow_role_name = #{allowRoleName},
where id = #{id}
